# Nanobanana API Reference

## Official Contract

Use the official Gemini `generateContent` API shape and replace the provider-specific values:

- Official base URL: `https://generativelanguage.googleapis.com`
- Third-party base URL: your Google-compatible Gemini endpoint, only when explicitly intended

- Official API key: `GEMINI_API_KEY`
- Third-party API key: the provider key

Optional third-party provider example:

- Zhizengzeng base URL: `https://api.zhizengzeng.com/google`
- Zhizengzeng API key: the user's ZZZ key
- Third-party confirmation: `NANOBANANA_ALLOW_THIRD_PARTY=1` or `--allow-third-party`

## Endpoint Safety

- The generation scripts are designed to fail closed when `NANOBANANA_BASE_URL` or `--base-url` is missing.
- Official Google endpoint is the recommended default: `https://generativelanguage.googleapis.com`
- If you point the scripts to any other hostname, they should require explicit third-party confirmation before sending API keys or user-provided files.

## Route

```http
POST {base_url}/v1beta/models/{model}:generateContent
Content-Type: application/json
X-goog-api-key: {api_key}
```

## Text To Image Request

```json
{
  "contents": [
    {
      "parts": [
        {
          "text": "Create a picture of a nano banana dish in a fancy restaurant with a Gemini theme"
        }
      ]
    }
  ],
  "generationConfig": {
    "responseModalities": ["TEXT", "IMAGE"]
  }
}
```

## Image Editing Request

Use the same route. Put the prompt and each input image into `parts`.

```json
{
  "contents": [
    {
      "parts": [
        {
          "text": "Using the provided image, change only the blue sofa to a vintage brown leather Chesterfield sofa. Keep everything else exactly the same."
        },
        {
          "inlineData": {
            "mimeType": "image/png",
            "data": "<base64>"
          }
        }
      ]
    }
  ],
  "generationConfig": {
    "responseModalities": ["TEXT", "IMAGE"],
    "imageConfig": {
      "aspectRatio": "16:9",
      "imageSize": "2K"
    }
  }
}
```

## Response Parsing

Read outputs from:

```json
{
  "candidates": [
    {
      "content": {
        "parts": [
          { "text": "..." },
          {
            "inlineData": {
              "mimeType": "image/png",
              "data": "<base64>"
            }
          }
        ]
      }
    }
  ]
}
```

## Supported Official Options

- `generationConfig.responseModalities`
- `generationConfig.imageConfig.aspectRatio`
- `generationConfig.imageConfig.imageSize`
- `generationConfig.thinkingConfig.thinkingLevel`
- `generationConfig.thinkingConfig.includeThoughts`

## Practical Notes

- `gemini-3.1-flash-image-preview` supports image generation and editing.
- `imageSize` uses official values like `512`, `1K`, `2K`, `4K`.
- `aspectRatio` uses official values like `1:1`, `3:2`, `16:9`, `21:9`.
- For edit workflows, do not invent a separate edit endpoint. Use `generateContent` with prompt plus image inputs.
- Prompt-only helpers such as `build_materials_figure_prompt.py` and `--print-prompt` should remain local-only and not send data to the network.

#!/usr/bin/env python3
"""Build materials-science figure prompts without calling the image API."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path


TEMPLATE_CHOICES = (
    "graphical-abstract",
    "mechanism-figure",
    "device-architecture",
    "processing-workflow",
)


def load_templates() -> dict:
    template_path = Path(__file__).resolve().parent.parent / "references" / "materials-science-figure-templates.json"
    return json.loads(template_path.read_text(encoding="utf-8"))


def build_prompt(background: str, figure_type: str, lang: str, style_note: str | None) -> str:
    templates = load_templates()
    try:
        prompt = templates[figure_type][lang].replace("{background}", background.strip())
    except KeyError as exc:
        raise SystemExit(f"Unknown template selection: {figure_type}/{lang}") from exc

    if style_note:
        prompt = f"{prompt}\n\nAdditional Style Requirement:\n{style_note.strip()}"
    return prompt


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Build a materials-science figure prompt.")
    parser.add_argument("background", nargs="?", help="Scientific background text.")
    parser.add_argument("--background-file", help="Read scientific background from a text or markdown file.")
    parser.add_argument(
        "--materials-figure",
        required=True,
        choices=TEMPLATE_CHOICES,
        help="Built-in materials-science figure subtype.",
    )
    parser.add_argument("--lang", choices=("en", "zh"), default="en", help="Template output language.")
    parser.add_argument("--style-note", help="Optional extra style requirement appended after the template.")
    return parser.parse_args()


def resolve_background(args: argparse.Namespace) -> str:
    if args.background_file:
        path = Path(args.background_file)
        if not path.is_file():
            raise SystemExit(f"Background file not found: {path}")
        return path.read_text(encoding="utf-8")
    if args.background:
        return args.background
    raise SystemExit("Provide scientific background as an argument or via --background-file.")


def main() -> int:
    args = parse_args()
    sys.stdout.write(build_prompt(resolve_background(args), args.materials_figure, args.lang, args.style_note))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env node

const fs = require("fs");
const path = require("path");
const { URL } = require("url");

const OFFICIAL_BASE_URL = "https://generativelanguage.googleapis.com";
const OFFICIAL_HOSTNAME = "generativelanguage.googleapis.com";
const DEFAULT_MODEL = process.env.NANOBANANA_MODEL || "gemini-3.1-flash-image-preview";
const DEFAULT_TIMEOUT = Number(process.env.NANOBANANA_TIMEOUT || "120");

function loadMaterialsFigureTemplates() {
  const templatePath = path.join(__dirname, "..", "references", "materials-science-figure-templates.json");
  return JSON.parse(fs.readFileSync(templatePath, "utf8"));
}

function parseArgs(argv) {
  const args = {
    prompt: "",
    promptFile: "",
    materialsFigure: "",
    lang: "en",
    styleNote: "",
    inputImages: [],
    outDir: "./output/nanobanana",
    prefix: "nanobanana",
    baseUrl: process.env.NANOBANANA_BASE_URL || "",
    model: DEFAULT_MODEL,
    apiKey: process.env.NANOBANANA_API_KEY || "",
    apiKeyFile: process.env.NANOBANANA_API_KEY_FILE || "",
    aspectRatio: "",
    imageSize: "",
    textOnly: false,
    includeThoughts: false,
    thinkingLevel: "",
    timeout: DEFAULT_TIMEOUT,
    printPrompt: false,
    allowThirdParty: false,
  };

  const parts = [...argv];
  if (parts.length === 0) {
    throw new Error("Usage: node scripts/generate_image.js [\"prompt\"] [--prompt-file file.md] [--input-image file.png]");
  }

  if (!parts[0].startsWith("--")) {
    args.prompt = parts.shift();
  }
  while (parts.length > 0) {
    const key = parts.shift();
    if (key === "--text-only") {
      args.textOnly = true;
      continue;
    }
    if (key === "--include-thoughts") {
      args.includeThoughts = true;
      continue;
    }
    if (key === "--print-prompt") {
      args.printPrompt = true;
      continue;
    }
    if (key === "--allow-third-party") {
      args.allowThirdParty = true;
      continue;
    }

    const value = parts.shift();
    if (!value) {
      throw new Error(`Missing value for ${key}`);
    }

    switch (key) {
      case "--input-image":
        args.inputImages.push(value);
        break;
      case "--materials-figure":
        args.materialsFigure = value;
        break;
      case "--prompt-file":
        args.promptFile = value;
        break;
      case "--lang":
        args.lang = value;
        break;
      case "--style-note":
        args.styleNote = value;
        break;
      case "--out-dir":
        args.outDir = value;
        break;
      case "--prefix":
        args.prefix = value;
        break;
      case "--base-url":
        args.baseUrl = value;
        break;
      case "--model":
        args.model = value;
        break;
      case "--api-key":
        args.apiKey = value;
        break;
      case "--api-key-file":
        args.apiKeyFile = value;
        break;
      case "--aspect-ratio":
        args.aspectRatio = value;
        break;
      case "--image-size":
        args.imageSize = value;
        break;
      case "--thinking-level":
        args.thinkingLevel = value;
        break;
      case "--timeout":
        args.timeout = Number(value);
        break;
      default:
        throw new Error(`Unknown argument: ${key}`);
    }
  }

  return args;
}

function imagePathToPart(imagePath) {
  if (!fs.existsSync(imagePath)) {
    throw new Error(`Input image not found: ${imagePath}`);
  }
  const ext = path.extname(imagePath).toLowerCase();
  const mimeType = ext === ".jpg" || ext === ".jpeg"
    ? "image/jpeg"
    : ext === ".webp"
      ? "image/webp"
      : "image/png";

  return {
    inlineData: {
      mimeType,
      data: fs.readFileSync(imagePath).toString("base64"),
    },
  };
}

function resolveBaseUrl(args) {
  if (!args.baseUrl) {
    throw new Error(
      `Missing base URL. Set NANOBANANA_BASE_URL or pass --base-url explicitly. Official Google example: ${OFFICIAL_BASE_URL}`,
    );
  }

  let parsed;
  try {
    parsed = new URL(args.baseUrl);
  } catch {
    throw new Error(`Invalid base URL: ${args.baseUrl}. Use an explicit https URL such as ${OFFICIAL_BASE_URL}.`);
  }

  if (parsed.protocol !== "https:") {
    throw new Error(`Invalid base URL: ${args.baseUrl}. Use an explicit https URL such as ${OFFICIAL_BASE_URL}.`);
  }

  return args.baseUrl.replace(/\/$/, "");
}

function assertEndpointAllowed(baseUrl, args) {
  const hostname = new URL(baseUrl).hostname;
  const allowThirdParty = args.allowThirdParty || process.env.NANOBANANA_ALLOW_THIRD_PARTY === "1";
  if (hostname !== OFFICIAL_HOSTNAME && !allowThirdParty) {
    throw new Error(
      "Refusing to send API keys or user-provided files to a third-party Gemini-compatible provider. " +
      "If you intend to use a non-official endpoint, set NANOBANANA_ALLOW_THIRD_PARTY=1 or pass --allow-third-party. " +
      `Official Google endpoint: ${OFFICIAL_BASE_URL}`,
    );
  }
}

function loadInputImages(imagePaths) {
  return imagePaths.map(imagePathToPart);
}

function resolvePrompt(args) {
  let rawPrompt = args.prompt;
  if (args.promptFile) {
    if (!fs.existsSync(args.promptFile)) {
      throw new Error(`Prompt file not found: ${args.promptFile}`);
    }
    rawPrompt = fs.readFileSync(args.promptFile, "utf8");
  }

  if (args.materialsFigure) {
    const subtype = loadMaterialsFigureTemplates()[args.materialsFigure];
    if (!subtype) {
      throw new Error(`Unknown materials figure subtype: ${args.materialsFigure}`);
    }
    if (!rawPrompt) {
      throw new Error("Provide scientific background as the positional prompt when using --materials-figure.");
    }
    let prompt = subtype[args.lang].replace("{background}", rawPrompt.trim());
    if (args.styleNote) {
      prompt += `\n\nAdditional Style Requirement:\n${args.styleNote}`;
    }
    return prompt;
  }

  if (!rawPrompt) {
    throw new Error("Missing prompt.");
  }
  return rawPrompt;
}

function resolveApiKey(args) {
  if (args.apiKey) {
    return args.apiKey;
  }
  if (args.apiKeyFile) {
    if (!fs.existsSync(args.apiKeyFile)) {
      throw new Error(`API key file not found: ${args.apiKeyFile}`);
    }
    return fs.readFileSync(args.apiKeyFile, "utf8").trim();
  }
  throw new Error("Missing API key. Set NANOBANANA_API_KEY, NANOBANANA_API_KEY_FILE, or pass --api-key.");
}

function buildPayload(args) {
  const parts = [{ text: resolvePrompt(args) }, ...loadInputImages(args.inputImages)];
  const payload = {
    contents: [
      {
        parts,
      },
    ],
    generationConfig: {
      responseModalities: args.textOnly ? ["TEXT"] : ["TEXT", "IMAGE"],
    },
  };

  if (args.aspectRatio || args.imageSize) {
    payload.generationConfig.imageConfig = {};
    if (args.aspectRatio) {
      payload.generationConfig.imageConfig.aspectRatio = args.aspectRatio;
    }
    if (args.imageSize) {
      payload.generationConfig.imageConfig.imageSize = args.imageSize;
    }
  }

  if (args.thinkingLevel || args.includeThoughts) {
    payload.generationConfig.thinkingConfig = {};
    if (args.thinkingLevel) {
      payload.generationConfig.thinkingConfig.thinkingLevel = args.thinkingLevel;
    }
    if (args.includeThoughts) {
      payload.generationConfig.thinkingConfig.includeThoughts = true;
    }
  }

  return payload;
}

async function requestJson(args) {
  const baseUrl = resolveBaseUrl(args);
  assertEndpointAllowed(baseUrl, args);
  const apiKey = resolveApiKey(args);

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), args.timeout * 1000);

  try {
    const response = await fetch(
      `${baseUrl}/v1beta/models/${args.model}:generateContent`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-goog-api-key": apiKey,
        },
        body: JSON.stringify(buildPayload(args)),
        signal: controller.signal,
      },
    );

    if (!response.ok) {
      const text = await response.text();
      throw new Error(`Request failed with HTTP ${response.status}: ${text}`);
    }
    return await response.json();
  } finally {
    clearTimeout(timeoutId);
  }
}

function mimeToExt(mimeType) {
  if (!mimeType) return ".png";
  if (mimeType.includes("jpeg")) return ".jpg";
  if (mimeType.includes("webp")) return ".webp";
  return ".png";
}

function saveOutputs(json, args) {
  const candidates = json.candidates || [];
  if (!candidates.length || !candidates[0].content || !Array.isArray(candidates[0].content.parts)) {
    throw new Error(`Unexpected response shape: ${JSON.stringify(json)}`);
  }

  fs.mkdirSync(args.outDir, { recursive: true });
  let imageIndex = 0;
  let textIndex = 0;

  for (const part of candidates[0].content.parts) {
    if (part.text) {
      textIndex += 1;
      const filePath = path.join(args.outDir, `${args.prefix}-text-${textIndex}.txt`);
      fs.writeFileSync(filePath, part.text, "utf8");
      console.log(filePath);
      continue;
    }

    const inlineData = part.inlineData || part.inline_data;
    if (!inlineData || !inlineData.data) {
      continue;
    }

    imageIndex += 1;
    const filePath = path.join(
      args.outDir,
      `${args.prefix}-${imageIndex}${mimeToExt(inlineData.mimeType || inlineData.mime_type)}`,
    );
    fs.writeFileSync(filePath, Buffer.from(inlineData.data, "base64"));
    console.log(filePath);
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.printPrompt) {
    process.stdout.write(`${resolvePrompt(args)}\n`);
    return;
  }
  const json = await requestJson(args);
  saveOutputs(json, args);
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});

#!/usr/bin/env python3
"""Generate or edit images with the Gemini generateContent API."""

from __future__ import annotations

import argparse
import base64
import json
import mimetypes
import os
import sys
import urllib.parse
import urllib.error
import urllib.request
from pathlib import Path


OFFICIAL_BASE_URL = "https://generativelanguage.googleapis.com"
OFFICIAL_HOSTNAME = "generativelanguage.googleapis.com"
DEFAULT_MODEL = "gemini-3.1-flash-image-preview"
DEFAULT_TIMEOUT = 120


def load_materials_figure_templates() -> dict:
    template_path = Path(__file__).resolve().parent.parent / "references" / "materials-science-figure-templates.json"
    return json.loads(template_path.read_text(encoding="utf-8"))


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Generate or edit images with Gemini generateContent.")
    parser.add_argument("prompt", nargs="?", help="Prompt text or scientific background for shortcut modes.")
    parser.add_argument(
        "--prompt-file",
        help="Read prompt text or scientific background from a text or markdown file.",
    )
    parser.add_argument(
        "--materials-figure",
        choices=tuple(load_materials_figure_templates().keys()),
        help="Use a built-in materials-science figure template.",
    )
    parser.add_argument(
        "--lang",
        choices=("en", "zh"),
        default="en",
        help="Template output language for shortcut modes.",
    )
    parser.add_argument(
        "--style-note",
        help="Optional extra style constraint appended after a shortcut template.",
    )
    parser.add_argument(
        "--input-image",
        action="append",
        default=[],
        help="Input image path. Repeat to provide multiple reference images.",
    )
    parser.add_argument("--out-dir", default="./output/nanobanana", help="Output directory.")
    parser.add_argument("--prefix", default="nanobanana", help="Saved filename prefix.")
    parser.add_argument(
        "--base-url",
        default=os.getenv("NANOBANANA_BASE_URL"),
        help=f"Gemini-compatible base URL. Must be set explicitly, e.g. {OFFICIAL_BASE_URL}.",
    )
    parser.add_argument("--model", default=os.getenv("NANOBANANA_MODEL", DEFAULT_MODEL))
    parser.add_argument(
        "--api-key",
        default=os.getenv("NANOBANANA_API_KEY"),
        help="API key. Defaults to NANOBANANA_API_KEY.",
    )
    parser.add_argument(
        "--api-key-file",
        default=os.getenv("NANOBANANA_API_KEY_FILE"),
        help="Path to a file containing the API key. Preferred when you do not want the key shown in the command line.",
    )
    parser.add_argument(
        "--aspect-ratio",
        help="Official Gemini image aspect ratio, e.g. 1:1, 16:9, 3:2.",
    )
    parser.add_argument(
        "--image-size",
        help="Official Gemini image size, e.g. 512, 1K, 2K, 4K.",
    )
    parser.add_argument(
        "--text-only",
        action="store_true",
        help="Request only text output.",
    )
    parser.add_argument(
        "--include-thoughts",
        action="store_true",
        help="Request returned thoughts when the provider supports it.",
    )
    parser.add_argument(
        "--thinking-level",
        choices=("minimal", "high", "Minimal", "High"),
        help="Gemini 3.1 Flash Image thinking level.",
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=int(os.getenv("NANOBANANA_TIMEOUT", str(DEFAULT_TIMEOUT))),
        help="HTTP timeout in seconds.",
    )
    parser.add_argument(
        "--print-prompt",
        action="store_true",
        help="Print the resolved final prompt and exit without calling the API.",
    )
    parser.add_argument(
        "--allow-third-party",
        action="store_true",
        help="Explicitly allow sending API keys and input files to a non-official Gemini-compatible provider.",
    )
    return parser


def resolve_base_url(args: argparse.Namespace) -> str:
    base_url = args.base_url
    if not base_url:
        raise SystemExit(
            "Missing base URL. Set NANOBANANA_BASE_URL or pass --base-url explicitly. "
            f"Official Google example: {OFFICIAL_BASE_URL}"
        )

    parsed = urllib.parse.urlparse(base_url)
    if parsed.scheme != "https" or not parsed.netloc:
        raise SystemExit(f"Invalid base URL: {base_url}. Use an explicit https URL such as {OFFICIAL_BASE_URL}.")
    return base_url.rstrip("/")


def assert_endpoint_allowed(base_url: str, args: argparse.Namespace) -> None:
    hostname = urllib.parse.urlparse(base_url).hostname or ""
    allow_third_party = args.allow_third_party or os.getenv("NANOBANANA_ALLOW_THIRD_PARTY") == "1"
    if hostname != OFFICIAL_HOSTNAME and not allow_third_party:
        raise SystemExit(
            "Refusing to send API keys or user-provided files to a third-party Gemini-compatible provider. "
            "If you intend to use a non-official endpoint, set NANOBANANA_ALLOW_THIRD_PARTY=1 "
            "or pass --allow-third-party. "
            f"Official Google endpoint: {OFFICIAL_BASE_URL}"
        )


def load_input_images(image_paths: list[str]) -> list[dict]:
    return [file_to_inline_part(path_str) for path_str in image_paths]


def file_to_inline_part(path_str: str) -> dict:
    path = Path(path_str)
    if not path.is_file():
        raise SystemExit(f"Input image not found: {path}")
    mime_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
    return {
        "inlineData": {
            "mimeType": mime_type,
            "data": base64.b64encode(path.read_bytes()).decode("ascii"),
        }
    }


def resolve_prompt(args: argparse.Namespace) -> str:
    raw_prompt = args.prompt
    if args.prompt_file:
        path = Path(args.prompt_file)
        if not path.is_file():
            raise SystemExit(f"Prompt file not found: {path}")
        raw_prompt = path.read_text(encoding="utf-8")

    if args.materials_figure:
        if not raw_prompt:
            raise SystemExit("Provide scientific background as the positional prompt when using --materials-figure.")
        template = load_materials_figure_templates()[args.materials_figure][args.lang]
        prompt = template.format(background=raw_prompt.strip())
        if args.style_note:
            prompt = f"{prompt}\n\nAdditional Style Requirement:\n{args.style_note}"
        return prompt

    if not raw_prompt:
        raise SystemExit("Missing prompt.")
    return raw_prompt


def resolve_api_key(args: argparse.Namespace) -> str:
    if args.api_key:
        return args.api_key
    if args.api_key_file:
        path = Path(args.api_key_file)
        if not path.is_file():
            raise SystemExit(f"API key file not found: {path}")
        return path.read_text(encoding="utf-8").strip()
    raise SystemExit("Missing API key. Set NANOBANANA_API_KEY, NANOBANANA_API_KEY_FILE, or pass --api-key.")


def build_payload(args: argparse.Namespace) -> dict:
    parts = [{"text": resolve_prompt(args)}]
    parts.extend(load_input_images(args.input_image))

    payload = {
        "contents": [
            {
                "parts": parts,
            }
        ]
    }

    generation_config: dict = {}
    generation_config["responseModalities"] = ["TEXT"] if args.text_only else ["TEXT", "IMAGE"]

    image_config: dict = {}
    if args.aspect_ratio:
        image_config["aspectRatio"] = args.aspect_ratio
    if args.image_size:
        image_config["imageSize"] = args.image_size
    if image_config:
        generation_config["imageConfig"] = image_config

    thinking_config: dict = {}
    if args.thinking_level:
        thinking_config["thinkingLevel"] = args.thinking_level
    if args.include_thoughts:
        thinking_config["includeThoughts"] = True
    if thinking_config:
        generation_config["thinkingConfig"] = thinking_config

    if generation_config:
        payload["generationConfig"] = generation_config

    return payload


def request_json(args: argparse.Namespace) -> dict:
    base_url = resolve_base_url(args)
    assert_endpoint_allowed(base_url, args)
    api_key = resolve_api_key(args)

    request = urllib.request.Request(
        f"{base_url}/v1beta/models/{args.model}:generateContent",
        data=json.dumps(build_payload(args)).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "X-goog-api-key": api_key,
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=args.timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise SystemExit(f"Request failed with HTTP {exc.code}: {body}") from exc
    except urllib.error.URLError as exc:
        raise SystemExit(f"Request failed: {exc.reason}") from exc


def save_parts(response_json: dict, out_dir: Path, prefix: str) -> list[str]:
    candidates = response_json.get("candidates") or []
    if not candidates:
        raise SystemExit(f"Unexpected response shape: {json.dumps(response_json, ensure_ascii=False)}")

    parts = ((candidates[0].get("content") or {}).get("parts")) or []
    if not parts:
        raise SystemExit(f"Unexpected response shape: {json.dumps(response_json, ensure_ascii=False)}")

    out_dir.mkdir(parents=True, exist_ok=True)
    outputs: list[str] = []
    image_index = 0
    text_index = 0

    for part in parts:
        text = part.get("text")
        if text:
            text_index += 1
            path = out_dir / f"{prefix}-text-{text_index}.txt"
            path.write_text(text, encoding="utf-8")
            outputs.append(str(path))
            continue

        inline_data = part.get("inlineData") or part.get("inline_data")
        if not inline_data:
            continue

        image_index += 1
        mime_type = inline_data.get("mimeType") or inline_data.get("mime_type") or "image/png"
        extension = mimetypes.guess_extension(mime_type) or ".png"
        path = out_dir / f"{prefix}-{image_index}{extension}"
        path.write_bytes(base64.b64decode(inline_data["data"]))
        outputs.append(str(path))

    if not outputs:
        raise SystemExit(f"No text or image parts found: {json.dumps(response_json, ensure_ascii=False)}")
    return outputs


def main() -> int:
    args = build_parser().parse_args()
    if args.print_prompt:
        print(resolve_prompt(args))
        return 0
    response_json = request_json(args)
    for output in save_parts(response_json, Path(args.out_dir), args.prefix):
        print(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Render publication-style scientific figures from a JSON spec."""

from __future__ import annotations

import argparse
import json
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path

_TMP_CACHE_ROOT = Path(tempfile.gettempdir()) / "nanobanana_plot_cache"
os.environ.setdefault("MPLCONFIGDIR", str(_TMP_CACHE_ROOT / "mplconfig"))
os.environ.setdefault("XDG_CACHE_HOME", str(_TMP_CACHE_ROOT / "xdg-cache"))

import matplotlib.pyplot as plt
import numpy as np


PALETTE = {
    "blue_main": "#0F4D92",
    "blue_secondary": "#3775BA",
    "green_1": "#DDF3DE",
    "green_2": "#AADCA9",
    "green_3": "#8BCF8B",
    "red_1": "#F6CFCB",
    "red_2": "#E9A6A1",
    "red_strong": "#B64342",
    "neutral": "#CFCECE",
    "neutral_dark": "#4D4D4D",
    "highlight": "#FFD700",
    "teal": "#42949E",
    "violet": "#9A4D8E",
}

DEFAULT_COLORS = [
    PALETTE["blue_main"],
    PALETTE["green_3"],
    PALETTE["red_strong"],
    PALETTE["teal"],
    PALETTE["violet"],
    PALETTE["neutral_dark"],
]

SUPPORTED_FORMATS = {"png", "pdf", "svg", "eps", "jpg", "jpeg", "tif", "tiff"}


@dataclass(frozen=True)
class FigureStyle:
    font_size: int = 16
    axes_linewidth: float = 2.5
    use_tex: bool = False
    font_family: tuple[str, ...] = ("DejaVu Sans", "Helvetica", "Arial", "sans-serif")


def apply_publication_style(style: FigureStyle) -> None:
    plt.rcParams.update(
        {
            "font.family": list(style.font_family),
            "font.size": style.font_size,
            "axes.linewidth": style.axes_linewidth,
            "axes.spines.right": False,
            "axes.spines.top": False,
            "legend.frameon": False,
            "svg.fonttype": "none",
            "text.usetex": style.use_tex,
        }
    )


def create_subplots(nrows: int, ncols: int, figsize: tuple[float, float]) -> tuple[plt.Figure, np.ndarray]:
    fig, axes = plt.subplots(nrows=nrows, ncols=ncols, figsize=figsize, squeeze=False)
    return fig, axes.reshape(-1)


def finalize_figure(
    fig: plt.Figure,
    out_path: str,
    formats: list[str],
    dpi: int,
    pad: float,
    close: bool,
) -> list[Path]:
    base = Path(out_path)
    base.parent.mkdir(parents=True, exist_ok=True)
    saved: list[Path] = []
    for fmt in formats:
        if fmt not in SUPPORTED_FORMATS:
            raise SystemExit(f"Unsupported format: {fmt}")
        path = base.with_suffix(f".{fmt}")
        fig.savefig(path, dpi=dpi, bbox_inches="tight", pad_inches=pad, facecolor="white")
        saved.append(path)
    if close:
        plt.close(fig)
    return saved


def read_spec(path: str) -> dict:
    spec_path = Path(path)
    if not spec_path.is_file():
        raise SystemExit(f"Spec file not found: {spec_path}")
    return json.loads(spec_path.read_text(encoding="utf-8"))


def resolve_color(name: str | None, index: int) -> str:
    if not name:
        return DEFAULT_COLORS[index % len(DEFAULT_COLORS)]
    return PALETTE.get(name, name)


def series_colors(series_count: int, colors: list[str] | None) -> list[str]:
    if colors:
        return [resolve_color(color, i) for i, color in enumerate(colors)]
    return [DEFAULT_COLORS[i % len(DEFAULT_COLORS)] for i in range(series_count)]


def coerce_1d(values: list[float], label: str) -> np.ndarray:
    arr = np.asarray(values, dtype=float)
    if arr.ndim != 1:
        raise SystemExit(f"{label} must be 1D.")
    return arr


def coerce_2d(values: list[list[float]], label: str) -> np.ndarray:
    arr = np.asarray(values, dtype=float)
    if arr.ndim != 2:
        raise SystemExit(f"{label} must be 2D.")
    return arr


def apply_axis_options(ax: plt.Axes, panel: dict) -> None:
    if "title" in panel:
        ax.set_title(panel["title"])
    if "xlabel" in panel:
        ax.set_xlabel(panel["xlabel"])
    if "ylabel" in panel:
        ax.set_ylabel(panel["ylabel"])
    if "xlim" in panel:
        ax.set_xlim(panel["xlim"])
    if "ylim" in panel:
        ax.set_ylim(panel["ylim"])
    if "xticks" in panel:
        ax.set_xticks(panel["xticks"])
    if "xticklabels" in panel:
        ax.set_xticklabels(panel["xticklabels"], rotation=panel.get("xtick_rotation", 0))
    if "yticks" in panel:
        ax.set_yticks(panel["yticks"])
    if "yticklabels" in panel:
        ax.set_yticklabels(panel["yticklabels"])
    if panel.get("hide_xticks"):
        ax.set_xticks([])
    if panel.get("hide_yticks"):
        ax.set_yticks([])
    if panel.get("grid"):
        ax.grid(True, alpha=panel.get("grid_alpha", 0.2), linewidth=panel.get("grid_linewidth", 1.0))


def annotate_bars(ax: plt.Axes, containers: list, fmt: str, fontsize: float, padding: float) -> None:
    for container in containers:
        for patch in container:
            height = patch.get_height()
            ax.annotate(
                fmt.format(height),
                (patch.get_x() + patch.get_width() / 2.0, height),
                textcoords="offset points",
                xytext=(0, padding),
                ha="center",
                va="bottom",
                fontsize=fontsize,
            )


def render_bar(ax: plt.Axes, panel: dict) -> None:
    categories = panel["categories"]
    series = coerce_2d(panel["series"], "series")
    labels = panel["labels"]
    if series.shape[1] != len(categories):
        raise SystemExit("Bar panel categories length must match series columns.")
    if len(labels) != series.shape[0]:
        raise SystemExit("Bar panel labels length must match number of series.")

    x = np.arange(len(categories), dtype=float)
    total_width = float(panel.get("bar_group_width", 0.8))
    width = total_width / max(series.shape[0], 1)
    colors = series_colors(series.shape[0], panel.get("colors"))
    edgecolor = resolve_color(panel.get("edgecolor"), 0) if panel.get("edgecolor") else "black"
    linewidth = float(panel.get("linewidth", 1.5))
    hatches = panel.get("hatches", [])

    containers = []
    for idx, values in enumerate(series):
        offsets = x - total_width / 2.0 + width * (idx + 0.5)
        hatch = hatches[idx] if idx < len(hatches) else None
        bars = ax.bar(
            offsets,
            values,
            width=width,
            label=labels[idx],
            color=colors[idx],
            edgecolor=edgecolor,
            linewidth=linewidth,
            hatch=hatch,
            alpha=float(panel.get("alpha", 1.0)),
        )
        containers.append(bars)

    ax.set_xticks(x)
    ax.set_xticklabels(categories, rotation=panel.get("xtick_rotation", 0))
    if panel.get("legend", True):
        ax.legend(loc=panel.get("legend_loc", "best"), ncol=panel.get("legend_ncol", 1))
    if panel.get("annotate"):
        annotate_bars(
            ax,
            containers,
            panel.get("annotate_fmt", "{:.2f}"),
            float(panel.get("annotate_fontsize", 10)),
            float(panel.get("annotate_padding", 3)),
        )


def render_trend(ax: plt.Axes, panel: dict) -> None:
    x = coerce_1d(panel["x"], "x")
    y_series = panel["y_series"]
    labels = panel["labels"]
    if len(y_series) != len(labels):
        raise SystemExit("Trend panel labels length must match y_series.")
    colors = series_colors(len(y_series), panel.get("colors"))

    for idx, series in enumerate(y_series):
        y = coerce_1d(series, f"y_series[{idx}]")
        if len(y) != len(x):
            raise SystemExit("Each trend series must match x length.")
        ax.plot(
            x,
            y,
            label=labels[idx],
            color=colors[idx],
            linewidth=float(panel.get("line_width", 2.5)),
            alpha=float(panel.get("alpha", 1.0)),
        )
        shadows = panel.get("shadow", [])
        if idx < len(shadows):
            shadow = coerce_1d(shadows[idx], f"shadow[{idx}]")
            if len(shadow) != len(x):
                raise SystemExit("Each shadow series must match x length.")
            ax.fill_between(x, y - shadow, y + shadow, color=colors[idx], alpha=float(panel.get("shadow_alpha", 0.15)))

    if panel.get("legend", True):
        ax.legend(loc=panel.get("legend_loc", "best"), ncol=panel.get("legend_ncol", 1))


def render_heatmap(ax: plt.Axes, panel: dict, fig: plt.Figure) -> None:
    matrix = coerce_2d(panel["matrix"], "matrix")
    im = ax.imshow(matrix, aspect=panel.get("aspect", "auto"), cmap=panel.get("cmap", "magma"))

    x_labels = panel.get("x_labels")
    y_labels = panel.get("y_labels")
    if x_labels:
        ax.set_xticks(np.arange(len(x_labels)))
        ax.set_xticklabels(x_labels, rotation=panel.get("xtick_rotation", 45), ha=panel.get("xtick_ha", "right"))
    if y_labels:
        ax.set_yticks(np.arange(len(y_labels)))
        ax.set_yticklabels(y_labels)
    if panel.get("annotate"):
        fmt = panel.get("annotate_fmt", "{:.2f}")
        for row in range(matrix.shape[0]):
            for col in range(matrix.shape[1]):
                ax.text(col, row, fmt.format(matrix[row, col]), ha="center", va="center", fontsize=panel.get("annotate_fontsize", 9))
    if panel.get("colorbar", True):
        cbar = fig.colorbar(im, ax=ax, fraction=panel.get("colorbar_fraction", 0.046), pad=panel.get("colorbar_pad", 0.04))
        if "colorbar_label" in panel:
            cbar.set_label(panel["colorbar_label"])


def render_scatter(ax: plt.Axes, panel: dict) -> None:
    x = coerce_1d(panel["x"], "x")
    y = coerce_1d(panel["y"], "y")
    if len(x) != len(y):
        raise SystemExit("Scatter x and y must match length.")
    color = resolve_color(panel.get("color"), 0)
    ax.scatter(
        x,
        y,
        label=panel.get("label"),
        color=color,
        s=float(panel.get("size", 50)),
        alpha=float(panel.get("alpha", 0.7)),
        edgecolors=panel.get("edgecolors"),
        linewidths=float(panel.get("linewidths", 0.0)),
    )
    if panel.get("legend") and panel.get("label"):
        ax.legend(loc=panel.get("legend_loc", "best"))


def render_legend_panel(ax: plt.Axes, panel: dict, rendered_axes: list[plt.Axes]) -> None:
    source_panel = int(panel["source_panel"])
    if source_panel >= len(rendered_axes):
        raise SystemExit("Legend panel source_panel is out of range.")
    handles, labels = rendered_axes[source_panel].get_legend_handles_labels()
    ax.set_axis_off()
    ax.legend(handles, labels, loc=panel.get("legend_loc", "center"), ncol=panel.get("legend_ncol", 1))


def render_panel(ax: plt.Axes, panel: dict, fig: plt.Figure, rendered_axes: list[plt.Axes]) -> None:
    panel_type = panel["type"]
    if panel_type == "bar":
        render_bar(ax, panel)
    elif panel_type == "trend":
        render_trend(ax, panel)
    elif panel_type == "heatmap":
        render_heatmap(ax, panel, fig)
    elif panel_type == "scatter":
        render_scatter(ax, panel)
    elif panel_type == "legend":
        render_legend_panel(ax, panel, rendered_axes)
    elif panel_type == "empty":
        ax.set_axis_off()
    else:
        raise SystemExit(f"Unsupported panel type: {panel_type}")

    if panel_type not in {"legend", "empty"}:
        apply_axis_options(ax, panel)
    if panel.get("axis_off"):
        ax.set_axis_off()


def build_style(spec: dict) -> FigureStyle:
    raw = spec.get("style", {})
    return FigureStyle(
        font_size=int(raw.get("font_size", 16)),
        axes_linewidth=float(raw.get("axes_linewidth", 2.5)),
        use_tex=bool(raw.get("use_tex", False)),
        font_family=tuple(raw.get("font_family", ["DejaVu Sans", "Helvetica", "Arial", "sans-serif"])),
    )


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Render a publication-style figure from a JSON spec.")
    parser.add_argument("spec_file", help="Path to the JSON figure spec.")
    parser.add_argument("--out-path", help="Base output path without extension. Defaults to spec path stem in ./output/plots/.")
    parser.add_argument("--formats", nargs="+", default=["png", "pdf", "svg"], help="Output formats.")
    parser.add_argument("--dpi", type=int, default=300, help="Output DPI.")
    parser.add_argument("--pad", type=float, default=0.05, help="Padding passed to savefig.")
    parser.add_argument("--keep-open", action="store_true", help="Do not close the matplotlib figure after saving.")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    spec = read_spec(args.spec_file)
    apply_publication_style(build_style(spec))

    layout = spec.get("layout", {})
    nrows = int(layout.get("nrows", 1))
    ncols = int(layout.get("ncols", 1))
    figsize = tuple(layout.get("figsize", [8, 6]))
    if len(figsize) != 2:
        raise SystemExit("layout.figsize must contain exactly two numbers.")

    fig, axes = create_subplots(nrows, ncols, (float(figsize[0]), float(figsize[1])))
    panels = spec.get("panels", [])
    if len(panels) > len(axes):
        raise SystemExit("Number of panels exceeds subplot slots.")

    rendered_axes: list[plt.Axes] = []
    for idx, panel in enumerate(panels):
        render_panel(axes[idx], panel, fig, rendered_axes)
        rendered_axes.append(axes[idx])
    for idx in range(len(panels), len(axes)):
        axes[idx].set_axis_off()

    if "suptitle" in spec:
        fig.suptitle(spec["suptitle"])
    fig.tight_layout(pad=float(layout.get("tight_layout_pad", 2.0)))

    if args.out_path:
        out_path = args.out_path
    else:
        spec_path = Path(args.spec_file)
        out_path = str(Path("output/plots") / spec_path.stem)

    saved = finalize_figure(fig, out_path, [fmt.lower() for fmt in args.formats], args.dpi, args.pad, not args.keep_open)
    for path in saved:
        print(path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
